package net.civeira.phylax.feature.observe.observedprobe.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbeMethodOptions;

class MethodVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property method of observed probe ")
  void test_method_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> MethodVO.tryFrom("_GET_"));
    Assertions.assertEquals(ObservedProbeMethodOptions.GET, MethodVO.tryFrom("GET").getMethod());
    Assertions.assertThrows(ConstraintException.class, () -> MethodVO.tryFrom(null));
    Assertions.assertEquals(ObservedProbeMethodOptions.GET,
        MethodVO.from(ObservedProbeMethodOptions.GET).getMethod());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> MethodVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ObservedProbeMethodOptions.GET + "]",
        MethodVO.from(ObservedProbeMethodOptions.GET).toString());
  }
}
